 a=np.clip(a,s.action_space.low,s.action_space.high);ob,success,done=s.step(a);acts.append(a.copy())
 if success:print('SUCCESS',s.t,flush=True);s.save_trajectory(acts,'/app/output/trajectory.npz');sys.exit()
def go(pos,n=60,grip=0,R=None,base=None):
 if R is None:R=d.site_xmat[site].reshape(3,3).copy()
 for k in range(n):
  jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,d,jp,jr,site)
  cur=d.site_xpos[site].copy();rot=d.site_xmat[site].reshape(3,3).copy()
  ep=np.array(pos)-cur;er=Rotation.from_matrix(R@rot.T).as_rotvec()
  J=np.vstack([jp[:,49:56],.25*jr[:,49:56]]);e=np.r_[ep,.25*er]
  dq=J.T@np.linalg.solve(J@J.T+.005*np.eye(6),e)
  a=np.zeros(11);a[3:10]=np.clip(dq,-.07,.07);a[10]=grip
  if base is not None:a[:3]=np.clip(np.array(base)-d.qpos[52:55],-.04,.04)
  step(a)
  if k%20==0:print('go',s.t,'site',cur.round(3),'goal',np.array(pos),'drawer',d.qpos[4].round(3),flush=True)
def pause(n,grip=0):
 for _ in range(n):a=np.zeros(11);a[10]=grip;step(a)
